"""Three complete contrasting original guitar works; original source bytes retained."""
import argparse,hashlib,json,re,subprocess,tempfile
from pathlib import Path
from import_bwv1012 import read_notes
from import_repertoire_batch4 import VOICE_MIDI
ROOT=Path(__file__).resolve().parents[1]
SOURCES=ROOT/'scripts/score-sources/repertoire-batch5'
PIECES=[
 dict(key='sor35_13',file='sorf_op35_no13',path='SorF/O35/sorf_op35_no13',title='Fernando Sor · Op.35 No.13 — Andante',option='Op.35 第13番 · アンダンテ',bpm=90,meter=[2,4],beats=64,bars=32,shift=0,sourceId=1945,credit='Fernando Sor / Glen Larsen / Mutopia (2014)',license='CC BY-SA 4.0',licenseUrl='https://creativecommons.org/licenses/by-sa/4.0/',repeat='No sectional repeats; written unfold patterns retained.'),
 dict(key='giuliani50_18',file='giuliani-op50n18',path='GiulianiM/O50/giuliani-op50n18',title='Mauro Giuliani · Op.50 No.18 — Allegretto',option='Op.50 第18番 · アレグレット',bpm=132,meter=[2,4],beats=33,bars=16,shift=-12,sourceId=1346,credit='Mauro Giuliani / Stephen Rhen / Mutopia (2008)',license='CC BY 3.0',licenseUrl='https://creativecommons.org/licenses/by/3.0/',repeat='No sectional repeats; 1-quarter pickup plus 16 full 2/4 bars.'),
 dict(key='carcassi60_9',file='carcassi-op60-09',path='CarcassiM/O60/carcassi-op60-09',title='Matteo Carcassi · Op.60 No.9 — Allegretto grazioso',option='Op.60 第9番 · アレグレット・グラツィオーソ（反復あり）',bpm=120,meter=[4,4],beats=248,bars=62,shift=0,sourceId=306,credit='Matteo Carcassi / Jeff Covey / Mutopia (2012)',license='Public Domain',licenseUrl='https://creativecommons.org/licenses/publicdomain/',repeat='Source MIDI explicitly performs A B C B C: 8+19+8+19+8 bars; complete written second-section repeat.')
]

def compile_midi(executable):
 with tempfile.TemporaryDirectory() as directory:
  for p in PIECES:
   source=SOURCES/(p['file']+'.ly')
   text=subprocess.run([str(Path(executable).with_name('convert-ly')),str(source)],capture_output=True,text=True,check=True).stdout
   text,n=re.subn(r'\\midi\s*\{',lambda _: '\\midi { '+VOICE_MIDI,text);assert n==1
   tmp=Path(directory)/(p['file']+'.ly');tmp.write_text(text)
   subprocess.run([executable,'-dno-print-pages','-dbackend=null','-o',str(SOURCES/p['file']),str(tmp)],check=True)

def build():
 songs,manifest={},[]
 for p in PIECES:
  events=[[a,n+p['shift'],d] for a,n,d in read_notes((SOURCES/(p['file']+'.midi')).read_bytes())]
  terms='Score edition placed in the public domain by its typesetter.' if p['license']=='Public Domain' else 'Derived score data: '+p['license']+'; retain attribution, license and modification notice.'+(' Share adaptations under the same license.' if 'SA' in p['license'] else '')+' Application code separate.'
  source={k:p[k] for k in ['credit','license','licenseUrl']}
  source.update(url=f"https://www.mutopiaproject.org/cgibin/piece-info.cgi?id={p['sourceId']}",terms=terms,modifications='Official convert-ly; LilyPond 2.24.4 separate MIDI voices; overlapping unisons retained. '+p['repeat']+' Source MIDI tempo retained as fixed audition tempo; expressive tempo changes not modeled. App articulation separate.',pitch=('Source MIDI already sounding pitch; shift 0.' if p['shift']==0 else 'Written treble-register MIDI lowered 12 semitones to guitar sounding pitch.')+' Original guitar work; no verified string allocation or fingering simulation.',endingStatus='終端確認済み（出典版の終わりの休符を含む）。')
  if p['key']=='carcassi60_9':source['modifications']+=' Header says Allegretto grazioso; source edition bibliography is unknown.'
  assert all(len(v)<=500 for v in source.values())
  songs[p['key']]=dict(score=dict(title=p['title'],bpm=p['bpm'],meter=p['meter'],endBeat=p['beats'],events=events),label=p['title'],option=p['option'],edition='全曲・'+('後半反復あり' if p['key']=='carcassi60_9' else '反復なし')+'・ギター実音',source=source)
  manifest.append({**p,'source':source,'notes':len(events),'noteEndBeats':max(a+d for a,n,d in events),'pitchRange':[min(e[1] for e in events),max(e[1] for e in events)],'lilypondUrl':'https://raw.githubusercontent.com/MutopiaProject/MutopiaProject/master/ftp/'+p['path']+'/'+p['file']+'.ly','sha256':{p['file']+ext:hashlib.sha256((SOURCES/(p['file']+ext)).read_bytes()).hexdigest() for ext in ['.ly','.midi']}})
 (ROOT/'synth-demo/repertoire-batch5.js').write_text('// Generated by import_repertoire_batch5.py. Per-piece score rights: CC BY-SA 4.0 / CC BY 3.0 / Public Domain; application code separate.\nconst repertoireBatch5 = '+json.dumps(songs,ensure_ascii=False,separators=(',',':')).replace('],[','],\n[')+';\n')
 (SOURCES/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
 print([(m['key'],m['notes'],m['beats'],m['pitchRange']) for m in manifest])
if __name__=='__main__':
 parser=argparse.ArgumentParser();parser.add_argument('--lilypond');args=parser.parse_args()
 if args.lilypond:compile_midi(args.lilypond)
 build()
